import type { Dir, HairStyle, HatId, OutfitId, Sprite, WalkFrames } from "./types";

/**
 * Pocket Gallery overworld people: 16x24 walking sprites. The bottom 16 rows
 * stand on the tile; the head rises into the tile above. GENERATED by the
 * art-people generator; edit the grids there, not here.
 *
 * Layers line up pixel for pixel: the head (rows 0-11) and the sleeves sit on
 * the same pixels in all three frames of a direction, so one hair, hat or
 * extra sprite per direction fits every frame. Draw order: body, outfit,
 * extras, hair, hat. Right is drawn; left is right mirrored.
 */

